SHIM(D3D12GetInterface) {
    if (A3) ST64(A3, 0);
    if (A1 && !memcmp((void *)A1, &CLSID_D3D12Debug_, 16) && is_debug_iid(A2)) { if (A3) ST64(A3, d3d12_debug_object()); RET(S_OK); }
    if (A1 && !memcmp((void *)A1, &CLSID_D3D12DeviceRemovedExtendedData_, 16) && d3d12_is_dred_settings_iid(A2)) {
        if (A3) ST64(A3, d3d12_dred_settings());
        RET(S_OK);
    }
    d3d12_log_once("D3D12GetInterface (non-debug class)");
    RET(E_NOINTERFACE_);
}

